 void switchGoal(String id){if(goalId.equals(id))return;switchConversation(id,"");}
 void switchAgent(String id){companion.agentGoals(id);}
 void save(){if(conversationId.isEmpty())return;try{a.store.saveConversation(conversationId,history,input==null?draftValue():input.getText().toString());}catch(IllegalArgumentException deleted){}}
 JSONObject message(String role,String text){JSONObject m=new JSONObject();GoalStore.put(m,"id",UUID.randomUUID().toString());GoalStore.put(m,"role",role);GoalStore.put(m,"text",text);GoalStore.put(m,"at",System.currentTimeMillis());return m;}
 final Runnable expiryTick=()->{if(visible)render();};
 void render(){TransitRetention.clean(history,System.currentTimeMillis());ui.removeCallbacks(expiryTick);long expiry=TransitRetention.next(history,System.currentTimeMillis());if(visible&&expiry!=Long.MAX_VALUE)ui.postDelayed(expiryTick,Math.max(1,expiry-System.currentTimeMillis()+1));messages.removeAllViews();if(goalId.isEmpty()){messages.addView(a.txt("어떤 목표를 함께 해볼까요?\n나의 누비에서 원하는 누비와 목표를 골라 주세요.",16,companionMode()?NubiCompanionUi.INK:GoalUi.INK,false));return;}if(character.equals("grades"))SchoolChatUi.card(this);if(history.length()==0)bubble(message("assistant","안녕, "+preset.name+"야. ‘"+goalTitle()+"’에서 뭘 도와줄까?"));int from=Math.max(0,history.length()-historyLimit);if(from>0){Button older=a.button("이전 대화 더 보기 ("+from+")",false);older.setOnClickListener(v->{historyLimit+=60;render();});messages.addView(older);}for(int i=from;i<history.length();i++)bubble(history.optJSONObject(i));SchoolChatWork.events(this);thread.post(()->thread.fullScroll(View.FOCUS_DOWN));}
 void bubble(JSONObject m){if(m==null)return;boolean user=m.optString("role").equals("user");LinearLayout row=new LinearLayout(a);row.setGravity(user?Gravity.RIGHT:Gravity.LEFT);LinearLayout b=companionMode()?new NubiCompanionUi.Bubble(a):box(user?0xffe4f0e9:modern()?Color.WHITE:0xffeeeef0,14);if(companionMode()){b.setPadding(dp(14),dp(10),dp(14),dp(10));((NubiCompanionUi.Bubble)b).setMaxWidth(dp(companion.bubbleWidthDp()));}b.setBackground(Ui.bg(companionMode()?(user?NubiCompanionUi.COMPOSER:NubiCompanionUi.PANEL):user?0xffe4f0e9:modern()?Color.WHITE:0xffeeeef0,20,a));TextView t=a.txt(m.optString("text"),companionMode()?16:15,companionMode()?NubiCompanionUi.INK:GoalUi.INK,false);if(companionMode()){t.setIncludeFontPadding(false);t.setLineSpacing(0,1f);}t.setTextIsSelectable(true);b.addView(t);String state=m.optString("state");if(!state.isEmpty())b.addView(a.txt(m.has("document")&&state.equals("completed")?"문서 생성 결과 · 아래 상태 확인":stateLabel(state),11,GoalUi.MUTED,false),Ui.match(a,-2,6));
  if(m.has("campusJobId"))SchoolChatWork.jobCard(this,b,m.optString("campusJobId"));
  JSONArray items=m.optJSONArray("items");if(items!=null)for(int j=0;j<items.length();j++){JSONObject item=items.optJSONObject(j);if(item==null||!GoalRules.safe(item.optString("url")))continue;LinearLayout c=box(Color.WHITE,10);c.setBackground(Ui.bg(Color.WHITE,14,a));c.addView(a.txt(item.optString("title"),14,GoalUi.INK,true));if(!item.optString("priceText").isEmpty())c.addView(a.txt(item.optString("priceText"),13,GoalUi.PURPLE,true));TextView link=a.txt(android.net.Uri.parse(item.optString("url")).getHost()+" ↗",12,GoalUi.PURPLE,false);link.setOnClickListener(v->showSource(item.optString("url")));c.addView(link);c.setOnClickListener(v->showSource(item.optString("url")));b.addView(c,Ui.match(a,-2,8));}
  JSONObject doc=m.optJSONObject("document");if(doc!=null){JSONObject manifest=doc.optJSONObject("manifest");String docState=doc.optString("state");b.addView(a.txt(docState.equals("uploaded")?"문서 업로드·원격 검증 완료":"문서 생성 · "+(docState.equals("needs_information")?"추가 정보 필요":docState.equals("draft_only")?"초안 저장":"업로드 연결 필요"),13,GoalUi.PURPLE,true));JSONArray files=manifest==null?null:manifest.optJSONArray("files");for(int n=0;files!=null&&n<files.length();n++){JSONObject file=files.optJSONObject(n);if(file==null)continue;String name=file.optString("name");if(!name.endsWith(".docx")&&!name.endsWith(".hwpx")&&!name.endsWith(".pdf"))continue;Button open=a.button(name+" 열기",false);open.setOnClickListener(v->openDocument(doc,file));b.addView(open,Ui.match(a,-2,6));JSONObject compatible=chatGptCompatibleFile(doc,file);if(compatible!=null){Button edit=a.button("ChatGPT에 DOCX 첨부",false);edit.setOnClickListener(v->editDocumentWithChatGpt(doc,compatible));b.addView(edit,Ui.match(a,-2,4));}}}
  if(modern()&&!user&&!m.optString("state").isEmpty()){LinearLayout actions=new LinearLayout(a);Button copy=a.button("복사",false);copy.setOnClickListener(v->{((android.content.ClipboardManager)a.getSystemService(Context.CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("누비 답변",m.optString("text")));a.toast("답변을 복사했어.");});actions.addView(copy);Button retry=a.button("요청 수정",false);retry.setOnClickListener(v->draft(previousUser(m.optString("id"))));actions.addView(retry);JSONArray log=m.optJSONArray("steps");if(log!=null&&log.length()>0){Button trace=a.button("실행 "+log.length()+"단계",false);trace.setOnClickListener(v->new AlertDialog.Builder(a).setTitle("Qwen 실행 기록").setMessage(GoalWorkspaceUi.stepText(log)).setPositiveButton("닫기",null).show());actions.addView(trace);}b.addView(actions);}
  row.addView(b,new LinearLayout.LayoutParams(-2,-2));messages.addView(row,Ui.match(a,-2,companionMode()?4:10));}

 String previousUser(String messageId){String text="";for(int n=0;n<history.length();n++){JSONObject m=history.optJSONObject(n);if(m==null)continue;if(messageId.equals(m.optString("id")))break;if(m.optString("role").equals("user"))text=m.optString("text");}return text;}
 void openDocument(JSONObject doc,JSONObject file){if(running||submitting){a.toast("작업이 끝난 뒤 문서를 열어줘.");return;}String name=file.optString("name");a.relay.document(doc.optString("job_id"),doc.optString("goalId",goalId),name,file.optString("sha256"),r->{if(r.has("error")){a.toast(r.optString("error"));return;}try{android.net.Uri u=android.net.Uri.parse(r.optString("uri"));companion.previewDocument(u,name);}catch(Exception e){a.toast("문서를 기기에 저장했어. DOCX/HWPX를 지원하는 앱이 필요해.");}});}
 JSONObject chatGptCompatibleFile(JSONObject doc,JSONObject file){if(file.optString("name").endsWith(".pdf"))return null;if(file.optString("name").endsWith(".docx"))return file;JSONObject manifest=doc.optJSONObject("manifest");JSONArray files=manifest==null?null:manifest.optJSONArray("files");for(int n=0;files!=null&&n<files.length();n++){JSONObject candidate=files.optJSONObject(n);if(candidate!=null&&candidate.optString("name").equals("budget.docx"))return candidate;}return null;}
 void editDocumentWithChatGpt(JSONObject doc,JSONObject file){if(running||submitting){a.toast("작업이 끝난 뒤 문서를 열어줘.");return;}String name=file.optString("name");a.relay.document(doc.optString("job_id"),doc.optString("goalId",goalId),name,file.optString("sha256"),r->{if(r.has("error")){a.toast(r.optString("error"));return;}try{android.net.Uri u=android.net.Uri.parse(r.optString("uri"));Intent i=new Intent(a,BrowserWorkspaceActivity.class).setData(u).putExtra("start_url","https://chatgpt.com/");companion.route(i);}catch(Exception e){a.toast("ChatGPT를 열지 못했어.");}});}
 static String stateLabel(String s){return s.equals("completed")?"탐색 결과 · 출처 확인 가능":s.equals("cancelled")?"중지됨 · 입력 내용은 보관했어":s.equals("running")?"탐색 중":s.equals("failed")?"실행 실패 · 다시 요청할 수 있어":"";}
 void showSource(String url){if(running||submitting){a.toast("탐색을 중지한 뒤 원문을 열어줘.");return;}if(companion!=null)companion.browser();a.selectedUrl=url;a.web.loadUrl(url);address.setText("원문 · "+android.net.Uri.parse(url).getHost());}
 void busy(boolean value){running=value;if(companion!=null&&progress!=null)progress.setVisibility(value?View.VISIBLE:View.GONE);send.setText(value?"■":"↑");send.setContentDescription(value?"탐색 중지":"메시지 전송");}
 void submit(){String text=input.getText().toString().trim();if(character.equals("grades")&&text.matches(".*(학교|포털|블랙보드|아웃룩|계정).*(연결|로그인).*")){history.put(message("user",text));history.put(message("assistant","학교 계정부터 연결해 볼게. 공식 로그인 화면에서 입력하면 나머지 서비스도 이어서 확인할게."));input.setText("");save();render();new SchoolSignIn(this).show();return;}if(!text.isEmpty()&&!SchoolChatWork.handle(this,text))a.runs.start(this,text);}
 void cancel(){a.runs.cancel();}
 void pause(){visible=false;ui.removeCallbacks(expiryTick);ui.removeCallbacks(schoolTick);save();}
 void resume(){visible=true;ui.removeCallbacks(schoolTick);ui.post(schoolTick);try{if(!a.relay.connected())a.relay.restore();}catch(Exception e){a.toast("연결을 확인해 주세요.");}a.runs.resume();syncRun();}
